<section class="analytics-domain-section"><div class="analytics-domain-heading"><div><span>Inventory</span><h2>Current stock summary</h2></div></div><section class="analytics-kpi-strip"><x-analytics.kpi label="Well Stocked" :value="number_format($inventory->healthy)" small="Above reorder threshold" icon="fa-box-open" tone="green"/><x-analytics.kpi label="Low Stock" :value="number_format($inventory->low)" small="At or below reorder threshold" icon="fa-triangle-exclamation" tone="yellow"/><x-analytics.kpi label="Needs Restock" :value="number_format($inventory->critical)" small="No stock on hand" icon="fa-box" tone="red"/><x-analytics.kpi label="Total Items" :value="number_format($inventory->total)" small="Inventory records" icon="fa-boxes-stacked"/></section></section>